"""Identifiers: UUID version 7 (RFC 9562), time-ordered, generated by the application.

Every document's `_id` is a UUIDv7 stored as a BSON UUID (binary subtype 4), so identifiers in
the API stay the same as before the move to MongoDB (docs/database-design.md §1).
"""

import os
import time
import uuid


def uuid7() -> uuid.UUID:
    """A new UUIDv7: 48 bits of Unix milliseconds, then 74 random bits."""
    milliseconds = time.time_ns() // 1_000_000
    value = (milliseconds & 0xFFFF_FFFF_FFFF) << 80
    value |= int.from_bytes(os.urandom(10), "big") & ((1 << 80) - 1)
    value &= ~(0xF << 76)
    value |= 0x7 << 76  # version 7
    value &= ~(0x3 << 62)
    value |= 0x2 << 62  # RFC 9562 variant
    return uuid.UUID(int=value)
